<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Requests\{CreatePortfolioRequest,UpdatePortfolioRequest};use App\Models\PortfolioItem;use App\Services\PortfolioManagementService;use Illuminate\Http\Request;class PortfolioController extends ApiController{public function __construct(private PortfolioManagementService $service){}public function index(Request $r){return $this->success($this->service->publicList($r->all()));}public function show(PortfolioItem $portfolio){abort_unless($portfolio->status==='ACTIVE',404);return $this->success($portfolio->load(['category','media']));}public function store(CreatePortfolioRequest $r){$this->admin($r);return response()->json(['data'=>$this->service->create($r->validated(),$r->user()),'meta'=>[]],201);}public function update(UpdatePortfolioRequest $r,PortfolioItem $portfolio){$this->admin($r);return $this->success($this->service->update($portfolio,$r->validated()));}public function destroy(Request $r,PortfolioItem $portfolio){$this->admin($r);$this->service->delete($portfolio);return response()->noContent();}private function admin(Request $r){abort_unless($r->user()->roles()->whereIn('name',['ADMIN','SUPER_ADMIN'])->exists(),403);}}
